	I2cDelay(MAX(SCL_HALF_DELAY, I2C_MIN_DELAY));

	// to default state.
	I2cSetSclLow();
	I2cDelay(SCL_DELAY);
}

static void I2cStop(void)
{
	// Just to ensure SCL is in LOW state.
	I2cSetSclLow();
	I2cDelay(SCL_HALF_DELAY);

	// SDA in LOW state, SCL in HIGH state
	I2cSetSdaLow();
	I2C_PIN_DELAY();

	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	// A LOW to HIGH transition on the SDA line while SCL is HIGH
	I2cSetSdaHigh();
	I2cDelay(SCL_DELAY);

	// to default state.
	/*
	I2cSetSclLow();
	I2cDelay(SCL_DELAY);
	*/ // should discard these codes for multi-master I2C bus.( or new devices of latest protocol. )
}

static inline void I2cAck(void)
{
	// Pull down SDA line.
	I2cSetSdaLow();
	I2C_PIN_DELAY();

	I2cSclPulse();
}

static inline void I2cNoAck(void)
{
	// let SDA line in HIGH state during ACK clock cycle.
	I2cSetSdaHigh();
	I2C_PIN_DELAY();

	I2cSclPulse();
}

/****************************************************************
 *
 * I2C Bus Driver routines.
 *
 ****************************************************************/
#if (CONFIG_TP_HY4633)
	#define I2C_SPECIAL_DELAY()		I2cDelay(550) // special timing requirements, the delay between bytes and bytes needs to be more than 25us.
#else
	#define I2C_SPECIAL_DELAY()
#endif

static void I2cInit( void )
{
	I2cSetSdaOutput();
	I2cSetSclOutput();
	//I2cSetSclLow();
	I2cStop();
}

static bool I2cWaitForAck(void)
{
	bool	Ack;

	I2cSetSdaInput();
	I2C_PIN_DELAY();

	I2cSetSclHigh();
	I2cDelay(SCL_DELAY);

	Ack = (I2cReadSda() == 0);

	I2C_PIN_DELAY();

	I2cSetSclLow();
	I2C_PIN_DELAY();

	I2cDelay(SCL_DELAY);
	//Please note - the following call is required because
	//the I2cSetSdaHigh and I2cSetSdaLow functions do not set the port to output state
	//I2cSetSdaOutput();

	I2C_SPECIAL_DELAY();

	return Ack;
}

static bool I2cSend(uint8_t I2cData)
{
	uint8_t	Mask;

	I2cSetSdaOutput();
	for(Mask = 128; Mask; Mask >>= 1)
	{
		if(I2cData & Mask)
		{
			I2cSetSdaHigh();
		}
		else
		{
			I2cSetSdaLow();
		}

		I2C_PIN_DELAY();

		if(Mask == 1)
		{
			//The 9th bit of ack would exchange the output/input direction
			//Change SDA PIN as input mode in time to improve wave not normative issue
			I2cSclPulse_ack();
		} else {
			I2cSclPulse();
		}
	}

	return I2cWaitForAck();
}

static uint8_t I2cReceive(bool LastOne)
{
	uint8_t		Mask;
	uint8_t		I2cData = 0;

	I2cSetSdaInput();
	I2C_PIN_DELAY();

	for(Mask = 128; Mask; Mask >>= 1)
	{
		I2cSetSclHigh();
		I2cDelay(SCL_DELAY);

		if(I2cReadSda())
		{
			I2cData |= Mask;
		}
		I2C_PIN_DELAY();

		I2cSetSclLow();
		I2cDelay(SCL_DELAY);
	}

	//Please note - the following call is required because
	//the I2cSetSdaHigh and I2cSetSdaLow functions do not return the port to output state
	I2cSetSdaOutput();
	I2C_PIN_DELAY();

	if(LastOne)
	{
		I2cNoAck();
	}
	else
	{
		I2cAck();
	}

	I2C_SPECIAL_DELAY();

	return I2cData;
}

static bool I2cWrite(uint8_t Addr, const uint8_t * pBuff, uint32_t len)
{
	bool ret = FALSE;

	// Acquire mutex to protect I2C bus access
	if (s_sim_i2c_mutex_initialized) {
		rtos_lock_mutex(&s_sim_i2c_mutex);
	}

	Addr <<= 1;

	I2cStart();

	if(I2cSend(Addr) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	while(len-- > 0)
	{
		if(I2cSend(*pBuff++) == FALSE)
		{
			I2cStop();
			goto exit;
		}
	}

	I2cStop();

	ret = TRUE;

exit:
	// Release mutex
	if (s_sim_i2c_mutex_initialized) {
		rtos_unlock_mutex(&s_sim_i2c_mutex);
	}

	return ret;
}

static bool I2cRead(uint8_t Addr, uint8_t * pBuff, uint32_t len)
{
	bool ret = FALSE;

	// Acquire mutex to protect I2C bus access
	if (s_sim_i2c_mutex_initialized) {
		rtos_lock_mutex(&s_sim_i2c_mutex);
	}

	if(len == 0)
	{
		goto exit;
	}

	Addr <<= 1;
	Addr |= 0x01;

	I2cStart();

	if(I2cSend(Addr) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	while(len > 0)
	{
		*pBuff++ = I2cReceive((--len) == 0);
	}

	I2cStop();

	ret = TRUE;

exit:
	// Release mutex
	if (s_sim_i2c_mutex_initialized) {
		rtos_unlock_mutex(&s_sim_i2c_mutex);
	}

	return ret;
}

static bool I2cMemWrite(i2c_id_t id, const i2c_mem_param_t *mem_param)
{
	uint32_t Addr;
	uint32_t mem_addr;
	uint8_t * pBuff;
	uint32_t len;
	uint32_t mem_addr_size;
	bool ret = FALSE;

	// Acquire mutex to protect I2C bus access
	if (s_sim_i2c_mutex_initialized) {
		rtos_lock_mutex(&s_sim_i2c_mutex);
	}

	Addr = mem_param->dev_addr;
	mem_addr = mem_param->mem_addr;
	pBuff = mem_param->data;
	len = mem_param->data_size;
	mem_addr_size = mem_param->mem_addr_size;

	Addr <<= 1;

	I2cStart();

	if(I2cSend(Addr) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	if (mem_addr_size == I2C_MEM_ADDR_SIZE_16BIT) {
		if(I2cSend((mem_addr >> 8) & 0xff) == FALSE)
		{
			I2cStop();
			goto exit;
		}
	}

	if(I2cSend((mem_addr & 0xff)) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	while(len-- > 0)
	{
		if(I2cSend(*pBuff++) == FALSE)
		{
			I2cStop();
			goto exit;
		}
	}

	I2cStop();

	ret = TRUE;

exit:
	// Release mutex
	if (s_sim_i2c_mutex_initialized) {
		rtos_unlock_mutex(&s_sim_i2c_mutex);
	}

	return ret;
}

static bool I2cMemRead(i2c_id_t id, const i2c_mem_param_t *mem_param)
{
	uint32_t Addr;
	uint32_t mem_addr;
	uint8_t * pBuff;
	uint32_t len;
	uint32_t mem_addr_size;
	bool ret = FALSE;

	// Acquire mutex to protect I2C bus access
	if (s_sim_i2c_mutex_initialized) {
		rtos_lock_mutex(&s_sim_i2c_mutex);
	}

	Addr = mem_param->dev_addr;
	mem_addr = mem_param->mem_addr;
	pBuff = mem_param->data;
	len = mem_param->data_size;
	mem_addr_size = mem_param->mem_addr_size;

	if(len == 0)
	{
		goto exit;
	}

	I2cStart();

	Addr <<= 1;
	if(I2cSend(Addr) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	if (mem_addr_size == I2C_MEM_ADDR_SIZE_16BIT) {
		if(I2cSend((mem_addr >> 8) & 0xff) == FALSE)
		{
			I2cStop();
			goto exit;
		}
	}

	if(I2cSend((mem_addr & 0xff)) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	// Special handling for CONFIG_AIRPLAY (required for MFI chip)
	// NOTE: MFI chip need add this stop signal and delay for 30 ms
#if defined(CONFIG_AIRPLAY) && CONFIG_SIM_I2C_HW_BOARD_V3
	I2cStop();
	rtos_delay_milliseconds(40);
#endif

	I2cStart();
	Addr |= 0x01;

	if(I2cSend(Addr) == FALSE)
	{
		I2cStop();
		goto exit;
	}

	while(len > 0)
	{
		*pBuff++ = I2cReceive((--len) == 0);
	}

	I2cStop();

	ret = TRUE;

exit:
	// Release mutex
	if (s_sim_i2c_mutex_initialized) {
		rtos_unlock_mutex(&s_sim_i2c_mutex);
	}

	return ret;
}

