static bool bk7258_i2c1_sda_read(void)
{
  return bk7258_gpio_read(BK7258_I2C1_SDA_PIN);
}

/* Diagnostic-only: temporarily switch SCL to input+pull-up and read its
 * physical level, then restore it as a driven output at the same level
 * bk7258_i2c1_scl_high()/_low() last set. Unlike SDA (which already has
 * a read path for ACK sampling), SCL in this driver is write-only --
 * bk7258_i2c1_scl_high()/_low() only ever write the output latch via
 * bk7258_gpio_output(), and nothing in the normal transaction path ever
 * reads back whether the physical SCL pin actually follows that latch.
 * This function exists purely to close that blind spot for one-shot
 * diagnostic logging (see bk7258_i2c1_write_reg()'s first-call probe),
 * not for use in the timing-critical bit-bang path itself (switching
 * pin direction mid-transaction would violate this driver's timing
 * budget and is not how real I2C SCL sampling should work outside of
 * clock-stretching support, which this driver does not implement). */
static bool bk7258_i2c1_scl_read_diag(bool restore_high)
{
  bool level;

  bk7258_gpio_input_pullup(BK7258_I2C1_SCL_PIN);
  bk7258_i2c1_delay();
  level = bk7258_gpio_read(BK7258_I2C1_SCL_PIN);

  if (restore_high)
    {
      bk7258_i2c1_scl_high();
    }
  else
    {
      bk7258_i2c1_scl_low();
    }

  return level;
}

