void bk7258_i2c1_init(void)
{
  /* No clock-gate/pinmux/interrupt setup needed: this is plain GPIO
   * bit-banging, not the hardware I2C1 peripheral (see this file's
   * header comment).  Idle the bus (both lines high) so the first
   * bk7258_i2c1_write_reg() call's START condition begins from a clean
   * idle state, matching sim_i2c_driver.c's I2cInit() (SetSdaOutput()
   * + SetSclOutput(), which this repo's bk7258_gpio_output(pin, true)
   * calls below achieve directly by driving both pins high). */
  bk7258_i2c1_sda_high();
  bk7258_i2c1_scl_high();

  /* One-shot diagnostic: unlike SDA (which has a dedicated read path
   * for ACK sampling), this driver's SCL is write-only in the normal
   * bit-bang path -- bk7258_i2c1_scl_high()/_low() only ever write the
   * output latch via bk7258_gpio_output(), and nothing else in this
   * file ever reads back whether the physical SCL pin follows that
   * latch.  Cross-checked against bk_avdk_smp's gpio_struct.h/gpio_ll.h
   * (this board's authoritative register layout) and confirmed the
   * output-latch write path itself (BK7258_GPIO_OUTPUT bit, and the
   * low-active BK7258_GPIO_OUTPUT_DISABLE bit's polarity handling in
   * bk7258_gpio_output()) matches the real hardware's documented
   * bit-field layout exactly -- so this probe closes the one remaining
   * gap that register-layout cross-check alone cannot answer: whether
   * the physical GPIO42 pad actually follows that correctly-written
   * latch, which requires actually switching it to input and reading
   * it back at least once. */
  printf("bk7258_i2c1: SCL physical read-back after driving HIGH: %d\n",
         (int)bk7258_i2c1_scl_read_diag(true));
  bk7258_i2c1_scl_low();
  printf("bk7258_i2c1: SCL physical read-back after driving LOW: %d\n",
         (int)bk7258_i2c1_scl_read_diag(false));
  bk7258_i2c1_scl_high();
}

