static void pan_display(int fb_device, FAR struct fb_planeinfo_s *plane_info)
{
  struct pollfd pfd;
  int ret;
  pfd.fd = fb_device;
  pfd.events = POLLOUT;

  ret = poll(&pfd, 1, 0);

  if (ret > 0)
    {
      ioctl(fb_device, FBIOPAN_DISPLAY, plane_info);
    }
}

