/****************************************************************************
 * Name: nxcamera_cmd_output
 *
 *   nxcamera_cmd_output() sets the output device/file for display/save.
 *
 *   Usage: output <path> [nframes]
 *
 *   - /dev/fbN          : display to framebuffer (default)
 *   - file.jpg/.jpeg    : image mode, saves 1 frame (nframes ignored)
 *   - file.mjpeg/.yuv/… : video mode, nframes (0/omitted=unlimited)
 *
 ****************************************************************************/

static int nxcamera_cmd_output(FAR struct nxcamera_s *pcam, FAR char *parg)
{
  int      ret;
  char     path[PATH_MAX];
  FAR char *ext;
  FAR char *space;
  bool     isimage = false;

  /* Parse optional frame count after the path */

  pcam->max_frames = 0;
  space = strchr(parg, ' ');
  if (space)
    {
      *space = '\0';
      pcam->max_frames = (uint32_t)atoi(space + 1);
    }

  /* First try to open the device directly */

  ret = nxcamera_setfb(pcam, parg);
  if (ret < 0)
    {
      /* Append the /dev path and try again */

      snprintf(path, sizeof(path), "/dev/%s", parg);
      ret = nxcamera_setfb(pcam, path);
    }

  /* Device doesn't exist or is not a video device. Treat as file */

  if (ret < 0)
    {
      if (ret == -ENODEV)
        {
          printf("Device %s is not an video device\n", parg);
          return ret;
        }

      ext = strrchr(parg, '.');
      if (ext && (ext != parg))
        {
          ext++;
          isimage = strncmp(ext, "jpg", sizeof("jpg")) == 0 ||
                    strncmp(ext, "jpeg", sizeof("jpeg")) == 0;
        }

      ret = nxcamera_setfile(pcam, parg, isimage);

      /* Image files (.jpg/.jpeg) always save exactly 1 frame */

      if (isimage)
        {
          pcam->max_frames = 1;
        }
    }

  if (ret < 0)
    {
      /* Create file error. Report error */

      printf("Error outputting to %s\n", parg);
    }

  /* Output device or file set successfully */

  return ret;
}

