        return ret;
    }

    if (*handle != NULL)
    {
        LOGD("%s, %d, already open\n", __func__, __LINE__);
        return ret;
    }

    dvp_driver_handle_t *dvp_handle = (dvp_driver_handle_t *)os_malloc(sizeof(dvp_driver_handle_t));
